        den=sum(max(0.,pref.get(a,0.)) for a in room)
        for a in room: w[a] += excess*(max(0.,pref.get(a,0.))/den if den else 1/len(room))
    total=sum(w.values())
    return {a:x/total for a,x in w.items()}

